using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 changed the default discriminator property from
            // "Discriminator" to "$type". Preserve the EF Core 8 property name
            // so existing 500K documents remain readable and direct SQL queries
            // referencing c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 no longer prepends the entity type to the id value.
            // New documents would get id "123" instead of "Product|123".
            // Preserve the EF Core 8 id format for compatibility with existing data.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .HasConversion(
                      id => $"Product|{id}",
                      stored => int.Parse(stored.Replace("Product|", "")));
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

